import { registerMessages } from '@/lib/i18n';

/** 产品导览（新手引导）文案。命名空间 tour.。 */
registerMessages({
  'tour.doneTitle': { zh: '教程完成 🎉', en: 'Tutorial complete 🎉' },
  'tour.doneBody1': { zh: '核心流程记住这条就够：', en: 'Remember this core flow and you are set:' },
  'tour.doneBody2': { zh: '**① 连接**页添加并**启用**连接 → **② 插件**页开**总开关** → **③** 回到该连接的**插件管理**为账号启用插件。', en: '**① Connections** page add and **enable** a connection → **② Plugins** page flip the **master switch** → **③** back to that connection’s **plugin management** to enable the plugin for the account.' },
  'tour.doneBody3': { zh: '祝你玩得开心！', en: 'Have fun!' },
  'tour.settingsTourTitle': { zh: '随时重看本教程', en: 'Replay this tutorial anytime' },
  'tour.settingsTourBody1': { zh: '以后想再走一遍这个导览，就来 **设置 → 新手引导** 点「重新查看产品导览」。', en: 'To walk through this tour again later, go to **Settings → Newbie guide** and click "Replay product tour".' },
  'tour.ucActionsTitle': { zh: '更新中心 ③ 主操作', en: 'Update center ③ main action' },
  'tour.ucActionsBody1': { zh: '主按钮会根据状态变成**安装更新 / 安装此版本**；没显式选版本时它是**检查更新**，不会误装旧版。下面还有**查看发布说明**。', en: 'The main button becomes **install update / install this version**; without an explicit version it is **check for updates**, so it never installs an older build by accident. Below it is **view release notes**.' },
  'tour.ucActionsBody2': { zh: '镜像源和测速都收在下面的「高级」里，日常更新不用管。', en: 'Mirror and speed test live under **Advanced** below — not needed for routine updates.' },
  'tour.ucVersionTitle': { zh: '更新中心 ② 安装版本', en: 'Update center ② install version' },
  'tour.ucVersionBody1': { zh: '**安装版本**：默认选当前通道的最新版本（正式版用户默认正式版，不会自动选 BETA / RC），也可展开挑一个**具体版本**来安装（比如想留在某个稳定版）。', en: '**Install version**: defaults to the latest release in your channel (stable users default to stable, never BETA / RC automatically), or expand it to pick a **specific version** (e.g. stay on a stable one).' },
  'tour.ucMirrorTitle': { zh: '更新中心 ④ 高级设置', en: 'Update center ④ advanced' },
  'tour.ucMirrorBody1': { zh: '**高级**：点开可以切换镜像源、给所有镜像测速（一键 Ping），或只测当前所选。国内访问 GitHub 慢或失败时换一个通常就好了。', en: '**Advanced**: open it to switch mirrors, speed-test all mirrors (Ping all), or test only the selected one. Switch when GitHub is slow or fails in China.' },
  'tour.ucMirrorBody2': { zh: '关键：**资源页（GitHub 源）与在线更新共用这一个镜像**——你在这选了哪个，资源列表 / 文档 / 下载就都走哪个。', en: 'Key: the **Resources page (GitHub source) and online updates share this one mirror** — whichever you pick here, the resource list / docs / download all go through it.' },
  'tour.ucMirrorCallout': { zh: '没手动选时会自动用测速最快的可用镜像；港澳台 / 国际网络通常可直连官方。', en: 'If you do not pick one manually, the fastest responding mirror is used automatically; users in Hong Kong, Macau, Taiwan or abroad can usually connect to the official source directly.' },
  'tour.ucHeaderTitle': { zh: '更新中心 ① 版本与状态', en: 'Update center ① version & status' },
  'tour.ucHeaderBody1': { zh: '悬浮窗打开了。顶部是**更新中心**标题和**上次检查时间**，下面是**检查状态**与**当前版本 → 最新版本**。', en: 'The popup is open. The top shows the **Update center** title and **last checked** time, followed by the **check status** and **current version → latest version**.' },
  'tour.ucHeaderBody2': { zh: '一眼就知道要不要更新；版本号旁的颜色标签（LTS / BETA / RC）表示正式版或预发布，预发布不会自动算作正式更新。', en: 'A glance tells you whether to update; the colored tag next to the version (LTS / BETA / RC) marks stable vs pre-release, and pre-releases never count as a stable update.' },
  'tour.updateCenterTitle': { zh: '最后 · 检查更新（版本号徽标）', en: 'Last · check for updates (version badge)' },
  'tour.updateCenterBody1': { zh: '侧边栏顶部这个**版本号徽标**就是「更新中心」入口，有新版本时右上角会有红色 NEW 气泡。', en: 'This **version badge** at the top of the sidebar is the "Update center" entry; a red NEW bubble appears top-right when a new version exists.' },
  'tour.updateCenterBody2': { zh: '下一步我直接帮你点开它，把里面的每一块都讲清楚。', en: 'Next I will open it for you and explain each block.' },
  'tour.settingsStoreOriginTitle': { zh: '设置 · 资源来源', en: 'Settings · resource source' },
  'tour.settingsStoreOriginBody1': { zh: '这里切换「资源」页从哪拉插件：**咔咔珂官方源** 或 **GitHub 社区源**。', en: 'Here switch where the "Resources" page pulls plugins from: **Kakake official source** or **GitHub community source**.' },
  'tour.settingsStoreOriginBody2': { zh: '点一下即时切换（带滑动动画）并自动保存，回到资源页就是新来源的列表。', en: 'Click to switch instantly (with slide animation) and auto-save; back on Resources it is the new source’s list.' },
  'tour.settingsStoreOriginCallout': { zh: 'GitHub 社区源是第三方投稿，安装前请自行甄别风险；官方源相对更稳妥。', en: 'The GitHub community source is third-party submissions; vet risk before installing; the official source is relatively safer.' },
  'tour.perfModeToggleTitle': { zh: '性能模式 · 三档开关', en: 'Performance mode · three-way switch' },
  'tour.perfModeToggleBody1': { zh: '**跟随设备**（默认）：按 CPU 核数 / 内存 / 实测帧率自动判定，iOS 设备默认降一档。', en: '**Follow device** (default): auto-decide by CPU cores / memory / measured frame rate; iOS defaults one notch down.' },
  'tour.perfModeToggleBody2': { zh: '**性能模式**：强制关闭实时模糊与氛围动画、暂停视频背景，用起来卡顿就选它。', en: '**Performance mode**: force off live blur and ambient animation, pause video background; pick if it lags.' },
  'tour.perfModeToggleBody3': { zh: '**完整特效**：玻璃拟态、动效、视频背景全开，好设备选它。', en: '**Full effects**: glassmorphism, animation, video background all on; pick on good devices.' },
  'tour.perfModeToggleCallout': { zh: '这个设置只保存在当前浏览器里，换设备互不影响。', en: 'This setting is stored only in the current browser, so it stays independent across devices.' },
  'tour.settingsPerformanceTitle': { zh: '接着 · 性能模式', en: 'Next · performance mode' },
  'tour.settingsPerformanceBody1': { zh: '这张 **性能模式** 卡片管的是整个控制台的「特效开销」。', en: 'This **Performance mode** card governs the console’s "effect cost".' },
  'tour.settingsPerformanceBody2': { zh: '它会自动判断你的设备性能，性能不够就自动关掉最吃性能的视觉效果（实时模糊、氛围动画等），让低配设备也能流畅用。', en: 'It auto-judges your device; if weak, it auto-turns off the most expensive visuals (live blur, ambient animation) so low-end devices stay smooth.' },
  'tour.colorPanelTitle': { zh: '拾色器 · 单色 / 渐变色', en: 'Color picker · single / gradient' },
  'tour.colorPanelBody1': { zh: '拾色器换成了 **Ant Design 的 ColorPicker**：面板上有「**单色 / 渐变色**」两个页签，单色照旧拖色盘、填颜色代码，选完即刻生效并自动保存。', en: 'The picker is now **Ant Design ColorPicker**: the panel has **Single / Gradient** tabs; single colors work as before (drag or paste a code), and changes apply instantly with auto-save.' },
  'tour.colorPanelBody2': { zh: '选「**渐变色**」后，在渐变条上**点一下加色标、拖动调位置、拖出去即删除**，再配合下方取色区给每个色标上色。', en: 'Switch to **Gradient** and click the bar to **add stops**, drag to reposition, drag out to remove; color each stop with the picker below.' },
  'tour.colorGradientTitle': { zh: '渐变色 · 预设与生效范围', en: 'Gradient · presets & where it applies' },
  'tour.colorGradientBody1': { zh: '面板左下角内置了一组**渐变预设**，点一下整条直接套用；不想用了切回「单色」页签即恢复。', en: 'The panel ships with **gradient presets** at the bottom-left — click to apply one; switch back to the **Single** tab to revert.' },
  'tour.colorGradientBody2': { zh: '渐变会实时作用于整站：**组件及按钮**落在主按钮的渐变面上，**品牌 Logo** 沿用渐变文字，**全局字体**的渐变染在标题上（正文保持单色可读）。', en: 'Gradients apply site-wide: **components & buttons** tint the primary button gradient, **brand Logo** keeps its gradient text, and the **global font** gradient colors headings (body text stays solid for readability).' },
  'tour.settingsColorTitle': { zh: '接着 · 配色方案', en: 'Next · color scheme' },
  'tour.settingsColorBody1': { zh: '这张 **配色方案** 卡片有三组独立配色：**全局字体**、**组件及按钮**、**品牌 Logo**，行尾的小色块就是当前色。', en: 'This **Color scheme** card has three independent color groups: **global font**, **components & buttons**, **brand Logo**; the small swatch at the row end is the current color.' },
  'tour.settingsColorBody2': { zh: '点色块会弹出**拾色盘**——下一步我直接帮你把「组件及按钮」的拾色盘打开，看看怎么选色。', en: 'Clicking a swatch opens a **color picker** — next I will open the "components & buttons" picker for you to see how to choose.' },
  'tour.apSidebarWidthMobileTitle': { zh: '外观 · 侧边栏宽度（手机）', en: 'Appearance · sidebar width (mobile)' },
  'tour.apSidebarWidthMobileBody1': { zh: '**侧边栏宽度 · 手机**：手机端侧边栏**占屏宽的百分比**，默认约三分之二。', en: '**Sidebar width · mobile**: the sidebar’s **percentage of screen width** on mobile, default about two-thirds.' },
  'tour.apSidebarWidthMobileBody2': { zh: '和电脑端是两根独立的调节线，各管一端、互不影响，自适应阈值也各算各的：低于 **40%** 导航改用两字短名，**25% ~ 39%** 只留文字（收掉图标），低于 **25%** 只留图标（最低 20%）。', en: 'An independent control line from desktop; each manages its own end, including its own thresholds: below **40%** entries switch to short names, **25–39%** shows text only (icons dropped), below **25%** shows icons only (20% minimum).' },
  'tour.apSidebarWidthPcTitle': { zh: '外观 · 侧边栏宽度（电脑）', en: 'Appearance · sidebar width (desktop)' },
  'tour.apSidebarWidthPcBody1': { zh: '**侧边栏宽度 · 电脑**：电脑端展开侧边栏时的**像素宽度**。', en: '**Sidebar width · desktop**: the **pixel width** of the expanded sidebar on desktop.' },
  'tour.apSidebarWidthPcBody2': { zh: '可调 **50–264px**，默认 204px。侧栏会自己降级：低于 **140px** 导航改用两字短名，低于 **105px** 带文字的按钮只留文字，低于 **80px** 连文字都放不下、只留图标——编辑、GitHub 这类纯图标按钮不受影响。', en: 'Adjustable from **50 to 264px**, default 204px. The sidebar downgrades itself: below **140px** entries switch to short names, below **105px** labelled buttons drop their icons, below **80px** even the text no longer fits so only icons remain — icon-only buttons such as Edit and GitHub keep theirs.' },
  'tour.apBackgroundBlurTitle': { zh: '外观 · 背景模糊度', en: 'Appearance · background blur' },
  'tour.apBackgroundBlurBody1': { zh: '**背景模糊度**：对你上传的**背景图 / 视频**整体做模糊。', en: '**Background blur**: blur your uploaded **background image / video** overall.' },
  'tour.apBackgroundBlurBody2': { zh: '背景太花影响读字时，调大它能让前景更清爽。', en: 'When the background is too busy to read text, raise it for a cleaner foreground.' },
  'tour.apCard2BlurTitle': { zh: '外观 · 悬浮层模糊度', en: 'Appearance · overlay blur' },
  'tour.apCard2BlurBody1': { zh: '**悬浮层模糊度**：悬浮窗那一类次级表面的毛玻璃模糊半径。', en: '**Overlay blur**: the frosted-glass blur radius of popup-style secondary surfaces.' },
  'tour.apCard2OpacityTitle': { zh: '外观 · 悬浮层透明度', en: 'Appearance · overlay opacity' },
  'tour.apCard2OpacityBody1': { zh: '**悬浮层透明度**：次级表面（**悬浮窗**、弹窗、下载气泡等）的透明度。', en: '**Overlay opacity**: the opacity of secondary surfaces (**popups**, dialogs, download bubbles, etc.).' },
  'tour.apCard2OpacityBody2': { zh: '想让弹窗更通透就调低它——它和「卡片」分开控制。', en: 'Lower it to make popups more transparent — controlled separately from "cards".' },
  'tour.apCardBlurTitle': { zh: '外观 · 卡片模糊度', en: 'Appearance · card blur' },
  'tour.apCardBlurBody1': { zh: '**卡片模糊度**：卡片背后的毛玻璃模糊半径，和上面的「卡片透明度」是一对。值越大背景越朦胧。', en: '**Card blur**: the frosted-glass blur radius behind cards, a pair with "card opacity" above. Higher = blurrier background.' },
  'tour.apCardOpacityTitle': { zh: '外观 · 卡片透明度', en: 'Appearance · card opacity' },
  'tour.apCardOpacityBody1': { zh: '**卡片透明度**：主要卡片（组件1）玻璃的通透程度。值越低越透、越能看见背景。', en: '**Card opacity**: how transparent the main cards (component 1) glass is. Lower = more see-through, more background visible.' },
  'tour.apUiSpeedTitle': { zh: '外观 · 动效速度', en: 'Appearance · animation speed' },
  'tour.apUiSpeedBody1': { zh: '**动效速度**：全站动画的快慢倍率。调大更利落、调小更舒缓。', en: '**Animation speed**: the speed multiplier for site-wide animations. Higher = snappier, lower = calmer.' },
  'tour.apBgTitle': { zh: '外观 · 自定义背景', en: 'Appearance · custom background' },
  'tour.apBgBody1': { zh: '最上面这两张卡分别给**竖屏 / 横屏**设置背景，可上传**图片**，也可上传 **mp4 / 实况视频**（自动循环播放）。', en: 'The top two cards set background for **portrait / landscape** respectively; you can upload an **image**, or an **mp4 / live photo video** (auto-loop).' },
  'tour.apBgBody2': { zh: '手机竖着用取竖屏那张，电脑 / 横屏取横屏那张。', en: 'Phone portrait uses the portrait one; desktop / landscape uses the landscape one.' },
  'tour.settingsAppearanceTitle': { zh: '重点 · 界面外观', en: 'Key · interface appearance' },
  'tour.settingsAppearanceBody1': { zh: '这张 **界面外观** 卡片能调整整个控制台的观感，可调的东西不少。', en: 'This **Interface appearance** card adjusts the whole console look; quite a few things to tune.' },
  'tour.settingsAppearanceBody2': { zh: '别急，下面我把里面每一样都带你过一遍——先是背景，再是各条滑动条。所有改动**即时预览、自动保存**，不用点保存。', en: 'Do not rush; I will go through each below — background first, then the sliders. All changes **preview live, auto-save**, no save click.' },
  'tour.brandTitleTitle': { zh: '自定义标题 · 生效位置', en: 'Custom title · where it takes effect' },
  'tour.brandTitleBody1': { zh: '改完就显示在**这里**——**顶栏**左侧的品牌字，也就是「应用标题 · 当前界面标题」的前半段。', en: 'After changing it shows **here** — the brand text at the **top-left of the top bar**, i.e. the first half of "app title · current screen title".' },
  'tour.brandTitleBody2': { zh: '侧边栏顶部显示的是同一个名字，所以电脑和手机上看到的是一致的。', en: 'The sidebar top shows the same name, so desktop and mobile see it consistently.' },
  'tour.brandTitleBody3': { zh: '**怎么才生效：输入自动存下后，刷新一次页面（或重进控制台），这里的标题就会变成你填的名字。**', en: '**How it takes effect: after auto-saving, refresh the page (or re-enter the console) and the title becomes your name.**' },
  'tour.brandTitleCallout': { zh: '如果没变，多半是还没刷新；刷新后即更新。', en: 'If it did not change, it probably has not refreshed yet; it updates right after a refresh.' },
  'tour.rowTitleTitle': { zh: '自定义标题 · 输入框', en: 'Custom title · input box' },
  'tour.rowTitleBody1': { zh: '在这里输入名字（最多 20 字），**输入即自动保存**，没有单独的保存按钮。', en: 'Type a name here (max 20 chars); **saves as you type**, no separate save button.' },
  'tour.rowTitleBody2': { zh: '留空则用默认「咔咔珂」。', en: 'Blank uses the default "Kakake".' },
  'tour.settingsTitleTitle': { zh: '再来 · 自定义标题', en: 'Next · custom title' },
  'tour.settingsTitleBody1': { zh: '这张 **自定义标题** 卡片可以把控制台顶部显示的「咔咔珂」改成你自己喜欢的名字。', en: 'This **Custom title** card can change the "Kakake" shown at the top of the console to a name you like.' },
  'tour.settingsTitleBody2': { zh: '下一步我带你看它填在哪、改完在哪生效、怎么才算生效。', en: 'Next I will show where to type it, where it takes effect, and how.' },
  'tour.rowTimeoutTitle': { zh: '运行参数 · API 超时', en: 'Runtime params · API timeout' },
  'tour.rowTimeoutBody1': { zh: '**API 超时**：调用 OneBot 接口的等待上限，单位**秒**，修改后立即生效。', en: '**API timeout**: wait limit for OneBot API calls, in **seconds**, takes effect immediately.' },
  'tour.rowTimeoutBody2': { zh: '发大文件 / 长视频容易超时，可以把它适当调大。', en: 'Large files / long videos easily time out; raise it a bit.' },
  'tour.rowLoglevelTitle': { zh: '运行参数 · 日志级别', en: 'Runtime params · log level' },
  'tour.rowLoglevelBody1': { zh: '**日志级别**：控制日志详细程度。**DEBUG** 看得最细（调试用），**INFO** 是日常默认，**WARN / ERROR** 只留警告 / 错误。', en: '**Log level**: controls log detail. **DEBUG** most detailed (debug), **INFO** daily default, **WARN / ERROR** only warnings / errors.' },
  'tour.rowLoglevelBody2': { zh: '这里调的是「记录多细」，配合日志页那个级别下拉「看哪一档」一起用。', en: 'This sets "how much to record"; pair with the level dropdown on the Logs page for "which level to view".' },
  'tour.settingsRuntimeTitle': { zh: '接着看 · 运行参数', en: 'Next · runtime params' },
  'tour.settingsRuntimeBody1': { zh: '这张 **运行参数** 卡片同样有两项可调，继续一项一项看。', en: 'This **Runtime params** card also has two adjustable items; continue field by field.' },
  'tour.rowPortTitle': { zh: '监听地址 · 后台端口', en: 'Listen address · backend port' },
  'tour.rowPortBody1': { zh: '**后台端口**：访问这个控制台用的端口，默认 **8787**，范围 1–65535。', en: '**Backend port**: the port to open this console, default **8787**, range 1–65535.' },
  'tour.rowPortBody2': { zh: '改了它，下次就要用新端口来打开控制台。', en: 'After changing it, you must use the new port to open the console next time.' },
  'tour.rowPortCallout': { zh: '端口改完同样需要重启咔咔珂才生效。', en: 'After changing the port you also need to restart Kakake for it to take effect.' },
  'tour.rowHostTitle': { zh: '监听地址 · 地址', en: 'Listen address · address' },
  'tour.rowHostBody1': { zh: '**监听地址**：控制台 / 服务在哪个网卡上对外提供。', en: '**Listen address**: which network interface the console / service serves on.' },
  'tour.rowHostBody2': { zh: '填 **0.0.0.0** = 允许所有网卡访问（想让别的设备 / 容器连进来用它）；填 **127.0.0.1** = 仅本机可访问。', en: '**0.0.0.0** = allow all interfaces (for other devices / containers); **127.0.0.1** = local only.' },
  'tour.rowHostCallout': { zh: '地址改完需要重启咔咔珂才生效。', en: 'After changing the address you need to restart Kakake for it to take effect.' },
  'tour.settingsListenTitle': { zh: '很好，来到「设置」页 · 监听地址', en: 'Good, the "Settings" page · listen address' },
  'tour.settingsListenBody1': { zh: '最后一站是「设置」页。这里的卡片我都按「先看整张卡片、再逐项讲」的方式带你过。', en: 'Last stop is the Settings page. I take you through its cards as "see the whole card first, then field by field".' },
  'tour.settingsListenBody2': { zh: '先看这张 **监听地址** 卡片，它有两项可调，下面一项一项说。', en: 'First this **Listen address** card; it has two adjustable items, explained one by one.' },
  'tour.navSettingsTitle': { zh: '最后一站 · 系统设置', en: 'Last stop · system settings' },
  'tour.navSettingsBody1': { zh: '最后一站是 **系统设置**：监听地址、端口、日志级别、界面外观、配色、性能、资源来源、更新，都在这一页。', en: 'Last stop is **System settings**: listen address, port, log level, appearance, colors, performance, resource source, updates — all on this page.' },
  'tour.navSettingsBody2': { zh: '内容比较多，下面我按卡片一张一张带你过。', en: 'Lots of content; I will go card by card.' },
  'tour.logsAutoscrollTitle': { zh: '操作 ⑤ 自动滚动（暂停键）', en: 'Action ⑤ auto-scroll (pause)' },
  'tour.logsAutoscrollBody1': { zh: '最右边的 **自动滚动** 开关其实就是「暂停键」。', en: 'The rightmost **auto-scroll** switch is essentially a "pause" button.' },
  'tour.logsAutoscrollBody2': { zh: '**关掉它**日志就不再实时刷入、画面定住，方便你盯住某一条慢慢看；需要新数据时点左边的刷新即可。', en: '**Turn it off** and logs stop streaming in live, the screen freezes so you can stare at one line; click refresh on the left for new data.' },
  'tour.logsClearTitle': { zh: '操作 ④ 清空', en: 'Action ④ clear' },
  'tour.logsClearBody1': { zh: '**清空**（红色）：清掉现有日志记录，会先弹确认框防误触。', en: '**Clear** (red): wipe existing log records, with a confirm first to prevent mis-clicks.' },
  'tour.logsClearBody2': { zh: '清空后新日志会照常继续产生，不影响运行。', en: 'After clearing, new logs keep coming as normal; does not affect running.' },
  'tour.logsClearCallout': { zh: '清空不可恢复，确认前最好先「下载」备份一份。', en: 'Clearing is irreversible, so download a backup first before you confirm.' },
  'tour.logsDownloadTitle': { zh: '操作 ③ 下载', en: 'Action ③ download' },
  'tour.logsDownloadBody1': { zh: '**下载**：导出**当前进程**的日志文件。', en: '**Download**: export the **current process** log file.' },
  'tour.logsDownloadBody2': { zh: '会带上你现在选的**分类 / 级别**筛选，只想导出报错就先选 ERROR 再下载。', en: 'It keeps your current **category / level** filter — to export only errors, pick ERROR then download.' },
  'tour.logsDownloadBody3': { zh: '比复制更全，适合把整份日志发给别人排查问题。', en: 'More complete than copy; good for sending the whole log to others for troubleshooting.' },
  'tour.logsCopyTitle': { zh: '操作 ② 复制可见日志', en: 'Action ② copy visible logs' },
  'tour.logsCopyBody1': { zh: '**复制可见日志**：把当前筛选后、屏幕上这些日志一次性复制到剪贴板。', en: '**Copy visible logs**: copy the currently filtered, on-screen logs to clipboard at once.' },
  'tour.logsCopyBody2': { zh: '方便你粘到群里 / 文档里求助或存档。', en: 'Handy to paste into a group / doc for help or archiving.' },
  'tour.logsRefreshTitle': { zh: '操作 ① 刷新', en: 'Action ① refresh' },
  'tour.logsRefreshBody1': { zh: '**刷新**：立即重新拉取最新日志。', en: '**Refresh**: immediately re-pull the latest logs.' },
  'tour.logsRefreshBody2': { zh: '关掉了「自动滚动」暂停接收后，想看新日志就点它。', en: 'After turning off "auto-scroll" to pause intake, click it to see new logs.' },
  'tour.logsToolbarTitle': { zh: '日志 · 底部操作条', en: 'Logs · bottom action bar' },
  'tour.logsToolbarBody1': { zh: '页面底部这条固定的操作栏一共有 **5 个操作**。', en: 'The fixed action bar at the bottom of the page has **5 actions**.' },
  'tour.logsToolbarBody2': { zh: '下面我一个一个带你看。', en: 'I will show them one by one.' },
  'tour.logsStreamTitle': { zh: '日志区 · 一行一条', en: 'Log area · one line each' },
  'tour.logsStreamBody1': { zh: '下面这片就是日志区：**一行一条**，按时间从旧到新往下排。', en: 'This area below is the log: **one line each**, oldest to newest top to bottom.' },
  'tour.logsStreamBody2': { zh: '每行固定按「**分类 · 连接账号 · 时间 · 摘要**」排列，整行颜色随分类走，报错行会整条变玫红加粗。', en: 'Each line is fixed as "**category · connection account · time · summary**", colored by category; an error line turns whole-line rose and bold.' },
  'tour.logsStreamBody3': { zh: '内容长时会**自动折行续排**（最多两行，再长就截断），所以不会出现横向滚动条把版面撑乱。', en: 'Long content **auto-wraps** (max two lines, then truncated) so no horizontal scrollbar messes the layout.' },
  'tour.logsStreamBody4': { zh: '图片 / 语音 / 视频这类消息会显示成 `[图片]` `[语音]` `[视频]` 这样的占位标记，不会把整屏撑开。', en: 'Image / voice / video messages show as `[image]` `[voice]` `[video]` placeholders, not stretching the screen.' },
  'tour.logsStreamBody5': { zh: '摘要里的**群号会自动显示成群名**、`@某人` 会显示成 **@昵称**，读起来比看一串数字友好得多（群名是框架记下来的，记过一次以后都认得）。', en: 'Group numbers in the summary auto-show as **group names**, `@someone` as **@nickname** — far friendlier than a string of digits (the framework remembers group names after first seen).' },
  'tour.logsStreamCallout': { zh: '想知道被截断的那一整条写了什么，点一下该行就能展开完整内容（JSON 会自动高亮）。', en: 'To see the full truncated line, click that row to expand the complete content (JSON is highlighted automatically).' },
  'tour.logsFileTitle': { zh: '过滤 · 选择（回看历史）', en: 'Filter · select (review history)' },
  'tour.logsFileBody1': { zh: '第三个下拉是 **选择**，用来临时查看**某一天的日志文件**。', en: 'The third dropdown is **select**, for temporarily viewing **a day’s log file**.' },
  'tour.logsFileBody2': { zh: '默认停在 **实时日志**；选一天就切到那天的存档，方便回看已经翻过去的内容。', en: 'Defaults to **live log**; pick a day to switch to that day’s archive, handy to review scrolled-away content.' },
  'tour.logsFileBody3': { zh: '注意这只是**临时查看**，刷新页面就会回到实时日志。', en: 'Note this is only **temporary** — refreshing the page returns to live log.' },
  'tour.logsLevelTitle': { zh: '过滤 · 级别下拉', en: 'Filter · level dropdown' },
  'tour.logsLevelBody1': { zh: '第二个下拉是 **级别** 筛选，点开可选：**全部级别**、**DEBUG**（最详细的调试信息）、**INFO**（常规运行信息）、**WARN**（警告）、**ERROR**（错误）。', en: 'The second dropdown is the **level** filter; open to choose: **All levels**, **DEBUG** (most detailed), **INFO** (normal), **WARN** (warning), **ERROR** (error).' },
  'tour.logsLevelBody2': { zh: '排查问题时选 **ERROR** 只看报错最快；想看最详细的过程，就配合「设置 → 运行参数」把日志级别调到 DEBUG，再回这里选 DEBUG。', en: 'When troubleshooting, pick **ERROR** to see only errors fastest; for the most detail, pair "Settings → Runtime params" to set log level to DEBUG, then pick DEBUG here.' },
  'tour.logsLevelCallout': { zh: '和搜索框一起用更快：先框定级别，再搜插件名或群号。', en: 'Use it together with the search box: narrow the level first, then search by plugin name or group ID.' },
  'tour.logsCatTitle': { zh: '过滤 · 分类下拉', en: 'Filter · category dropdown' },
  'tour.logsCatBody1': { zh: '搜索框旁的第一个下拉是 **分类** 筛选，点开可选：**全部分类** 或下面这些具体来源——', en: 'The first dropdown by the search box is the **category** filter; open to choose: **All categories** or these specific sources —' },
  'tour.logsCatBody2': { zh: '**系统**（框架自身）、**上报**（收到的消息 / 事件）、**输出**（调用 OneBot 接口）、**插件**（插件打的日志）；官方通道另有 **官方上报 / 官方输出 / 官方插件**；工具页模拟则有 **模拟上报 / 模拟输出**。', en: '**System** (the framework itself), **Report** (received messages / events), **Output** (OneBot API calls), **Plugin** (plugin logs); official channel also has **Official report / Official output / Official plugin**; simulated has **Sim report / Sim output**.' },
  'tour.logsCatBody3': { zh: '选一项就只看那一类，排查特定环节时非常快。', en: 'Pick one to see only that kind — very fast when troubleshooting a specific stage.' },
  'tour.logsSearchTitle': { zh: '过滤 · 搜索框', en: 'Filter · search box' },
  'tour.logsSearchBody1': { zh: '**搜索框**：按关键词实时过滤日志，比如输入插件名、报错关键字、群号来快速定位。', en: '**Search box**: filter logs live by keyword, e.g. type a plugin name, error keyword, or group number to locate quickly.' },
  'tour.logsFiltersTitle': { zh: '日志 · 顶部过滤区', en: 'Logs · top filter area' },
  'tour.logsFiltersBody1': { zh: '出问题先来「日志」页。顶部这一行是**过滤区**：一个搜索框 + 旁边三个下拉（**分类 / 级别 / 选择**）。', en: 'When something breaks, come to the "Logs" page first. The top row is the **filter area**: a search box + three dropdowns beside it (**category / level / select**).' },
  'tour.logsFiltersBody2': { zh: '下面我把这几样一个一个讲清楚。', en: 'I will explain each below.' },
  'tour.navLogsTitle': { zh: '下一站 · 运行日志', en: 'Next · runtime logs' },
  'tour.navLogsBody1': { zh: '倒数第二站是 **运行日志**。插件没反应、机器人连不上、想知道刚才到底发生了什么——都来这里看。', en: 'Second to last is **Runtime logs**. Plugin not responding, bot not connecting, want to know what just happened — come here.' },
  'tour.navLogsBody2': { zh: '点它进入日志页。', en: 'Click to enter the logs page.' },
  'tour.simConfigEventTitle': { zh: '模拟设置 · 事件上报', en: 'Simulate settings · event reporting' },
  'tour.simConfigEventBody1': { zh: '不止发消息——这里能模拟各类**通知 / 请求事件**：入群、退群、禁言、戳一戳、群文件上传、加好友 / 加群请求等。', en: 'Not just messages — here you can simulate various **notice / request events**: join, leave, mute, poke, group file upload, friend / group add requests, etc.' },
  'tour.simConfigEventBody2': { zh: '选事件类型后按提示填参数（群号、目标 QQ、时长、验证消息……），点触发，插件就会收到对应事件，用来测试进群欢迎、审批等逻辑。', en: 'Pick an event type, fill params per the hints (group number, target QQ, duration, verify message…), click trigger, and the plugin receives the corresponding event — to test join-welcome, approval logic, etc.' },
  'tour.simConfigEventCallout': { zh: '面板底部还有「清空缓存」清空当前会话记录、「完成」关闭面板。', en: 'At the bottom of the panel there is also Clear cache to wipe the current session log, and Done to close the panel.' },
  'tour.simConfigIdentityTitle': { zh: '模拟设置 · 发送身份', en: 'Simulate settings · sender identity' },
  'tour.simConfigIdentityBody1': { zh: '**群聊 / 私聊** 切换：决定这条消息是从群里还是私聊发来的。', en: '**Group / private** toggle: decides whether this message comes from a group or a private chat.' },
  'tour.simConfigIdentityBody2': { zh: '下面填**群号**（群聊时）、**发送者 QQ**、**昵称**——插件里 group_id、user_id、发送者昵称取到的就是这些值，方便你精确构造测试场景。', en: 'Below fill **group number** (for group), **sender QQ**, **nickname** — these are what the plugin’s group_id, user_id, sender nickname read, so you can build precise test scenarios.' },
  'tour.simConfigAccountTitle': { zh: '模拟设置 · 账号', en: 'Simulate settings · account' },
  'tour.simConfigAccountBody1': { zh: '这就是长按发送键呼出的「模拟设置」面板。', en: 'This is the "Simulate settings" panel brought up by long-pressing send.' },
  'tour.simConfigAccountBody2': { zh: '**账号**：选择要调试哪一个机器人连接——插件会以这个账号的身份收到模拟消息；官方账号会走 openid 语义。', en: '**Account**: choose which bot connection to debug — the plugin receives the simulated message as this account; official accounts use openid semantics.' },
  'tour.simulateTitle': { zh: '模拟消息 · 输入栏', en: 'Simulated messages · input bar' },
  'tour.simulateBody1': { zh: '底部就是输入栏，输入文字点这颗发送键，就能让插件「收到」一条消息。', en: 'The bottom is the input bar; type and click this send key to make a plugin "receive" a message.' },
  'tour.simulateBody2': { zh: '重点：**长按发送键约 3 秒**，会呼出 **「模拟设置」** 面板。下一步我直接帮你打开它，逐块讲解。', en: 'Key point: **long-press the send key about 3 seconds** to bring up the **"Simulate settings"** panel. Next I will open it for you, block by block.' },
  'tour.simulateCallout': { zh: '输入栏左侧「+」可插入 图片 / @ / 视频 / 语音 / JSON卡片。插件的回复与 API 调用会被拦截展示，不会真的发出去。', en: 'The "+" left of the input inserts image / @ / video / voice / JSON card. Plugin replies and API calls are intercepted and shown, never actually sent.' },
  'tour.navSimulateTitle': { zh: '下一站 · 模拟消息', en: 'Next · simulated messages' },
  'tour.navSimulateBody1': { zh: '再往下是 **模拟消息**——它在侧边栏有**独立入口**，不在工具箱里。', en: 'Further down is **Simulated messages** — it has its **own entry** in the sidebar, not in the toolbox.' },
  'tour.navSimulateBody2': { zh: '它能在本机假装收到一条消息 / 事件，真实触发插件来调试，不用真去群里发。', en: 'It fakes receiving a message / event locally to truly trigger plugins for debugging, no need to post in a group.' },
  'tour.navSimulateBody3': { zh: '这是开发 / 排查插件时最常用的一样，下面单独带你走一遍它的设置。', en: 'Most used when developing / troubleshooting plugins; I will walk through its settings separately.' },
  'tour.aiSendTitle': { zh: '输入区 · 发送键', en: 'Input area · send key' },
  'tour.aiSendBody1': { zh: '最右边这颗就是**发送**。空闲时点它发出消息；**AI 正在执行时**它会变成停止 / 排队键——点它可打断当前这一轮，或把新消息排进队列。', en: 'The rightmost is the **send**. Idle, it sends; **while the AI is running** it becomes stop / queue — click to interrupt the current round or queue a new message.' },
  'tour.aiSendBody2': { zh: '回车发送、Shift+回车换行。执行过程中会实时显示思考过程与改动的文件，结束后底部会留一行「已完成 / 执行中断」的结果。', en: 'Enter sends, Shift+Enter newline. The run shows thinking and changed files live; a "Done / interrupted" line stays at the bottom.' },
  'tour.aiFileTitle': { zh: '输入区 · 挂文件 / 图片', en: 'Input area · attach file / image' },
  'tour.aiFileBody1': { zh: '这个**文件夹图标**是**添加文件 / 图片**：让它照着你本地的文件来回答问题或改代码。', en: 'This **folder icon** is **add file / image**: let it answer or edit code based on your local file.' },
  'tour.aiFileBody2': { zh: '挂上去的文件会在输入框上方显示成小气泡，点 × 可移除；**拖文件进页面**效果一样。', en: 'Attached files show as bubbles above the input; click × to remove; **dragging a file into the page** does the same.' },
  'tour.aiFileCallout': { zh: '图片只有在模型开了「图片识别」时才会真的发给它；没开的话只会把文件名告诉它（气泡会带琥珀色描边提示）。', en: 'The image is only actually sent when the model has image recognition on; otherwise only the file name is passed (the bubble shows an amber outline as a hint).' },
  'tour.aiModelTitle': { zh: '输入区 · 选择模型服务', en: 'Input area · pick model service' },
  'tour.aiModelBody1': { zh: '这里显示**当前用的模型服务**，点开可切换成你配好的另一个（比如从便宜的换到强的）。', en: 'This shows the **current model service**; click to switch to another you configured (e.g. from cheap to strong).' },
  'tour.aiModelBody2': { zh: '菜单最后一项「添加 / 管理模型服务…」会直接跳到刚才那个配置弹窗。', en: 'The last menu item "Add / manage model services…" jumps to that config popup.' },
  'tour.aiModelBody3': { zh: '还没配模型时这里显示「选择模型」，点了就去配。', en: 'When no model is set it shows "Pick model"; clicking goes to configure.' },
  'tour.aiComposerTitle': { zh: '对话里 · 输入区', en: 'In a chat · input area' },
  'tour.aiComposerBody1': { zh: '进到某个会话后，底部这块就是**输入区**：上面打字，下面一行是**选择模型 / 添加文件 / 发送**。', en: 'In a session, this bottom block is the **input area**: type above, a row below for **pick model / add file / send**.' },
  'tour.aiComposerBody2': { zh: '**直接把文件拖进页面**也能挂上去，和点文件夹按钮是同一条路径。', en: '**Dragging a file into the page** also attaches it — same path as the folder button.' },
  'tour.aiComposerBody3': { zh: '执行中再点发送 = 把新消息**加入排队**，不会打断正在跑的那一轮。', en: 'Clicking send while running **queues** the new message without interrupting the current round.' },
  'tour.aiProfileVisionTitle': { zh: '添加模型 · 图片识别开关', en: 'Add model · image recognition switch' },
  'tour.aiProfileVisionBody1': { zh: '最后这个 **图片识别（多模态）** 默认是**关**的：只有勾上它，你在对话里挂的图片才会真的发给模型。', en: 'The last **image recognition (multimodal)** defaults **off**: only when ticked are images you attach in chat actually sent to the model.' },
  'tour.aiProfileVisionBody2': { zh: '模型其实不支持图片也没关系——上游会以 400 拒收，系统会自动去掉图片重试，不会把任务中断。', en: 'If the model does not support images, the upstream rejects with 400 and the system auto-strips the image and retries — the task is not interrupted.' },
  'tour.aiProfileVisionCallout': { zh: '图片按输入 token 计费且不便宜，用不上就别开。Anthropic 协议还会多一个「提示词缓存」选项，官方直连建议开，能省约九成输入费用。', en: 'Images are billed by input token and are not cheap, so leave it off if you do not need it. The Anthropic protocol adds a prompt caching option; for official direct connections it is recommended to turn it on, saving about 90 percent of input cost.' },
  'tour.aiProfileEditTitle': { zh: '添加模型 · 表单怎么填', en: 'Add model · how to fill the form' },
  'tour.aiProfileEditBody1': { zh: '点「添加模型」就进到这张表单。**最上面一排是预设**（常见厂商一键填入地址），有你用的就直接点，省得手打。', en: 'Click "Add model" to open this form. The **top row is presets** (one click fills the address for common vendors) — use it if yours is listed, saves typing.' },
  'tour.aiProfileEditBody2': { zh: '要填的就这几项：**显示名称**（自己认得就行）、**请求协议**（OpenAI 兼容 / Anthropic）、**服务器地址**、**API Key**、**请求路径**（留空走默认）、**模型名称**（可点「获取模型」自动拉列表，也可手填）。', en: 'Fields to fill: **display name** (anything you recognize), **request protocol** (OpenAI-compatible / Anthropic), **server address**, **API Key**, **request path** (blank = default), **model name** (click "Get models" to auto-list, or type).' },
  'tour.aiProfileEditBody3': { zh: '再下面是可选的调参：**思考强度**（开思考会让模型先想再答）、**最大输出 Token**、**超时**、**失败重试次数**。', en: 'Below are optional tweaks: **thinking budget** (on = think before answering), **max output tokens**, **timeout**, **retry count on failure**.' },
  'tour.aiProfileEditBody4': { zh: '填完点**保存并测试**最稳妥——它会存下来的同时测一次连通性，通了就直接能用。', en: 'Click **Save & test** when done — safest: it saves and tests connectivity at once; if it passes, it works immediately.' },
  'tour.aiProfileEditCallout': { zh: '开了「思考强度」的话，最大输出 Token 建议不低于 8192：思考内容也占这个额度，给少了会出现「只在思考、没有回复」。', en: 'If you enable thinking budget, set the max output tokens to at least 8192: reasoning also consumes this quota, and too little leads to thinking only with no reply.' },
  'tour.aiProfileTitle': { zh: '模型服务 · 添加与管理', en: 'Model service · add & manage' },
  'tour.aiProfileBody1': { zh: '这里列出所有模型服务：**点名字**把它设为当前使用（当前那个有青色描边），旁边可**测试连通性**（显示正常 / 失败）、**编辑**、**删除**。', en: 'This lists all model services: **click the name** to set it as current (the current one has a teal outline); beside it you can **test connectivity** (shows ok / fail), **edit**, **delete**.' },
  'tour.aiProfileBody2': { zh: '点 **添加模型** 填：名称、协议（OpenAI / Anthropic）、接口地址、密钥、模型名，是否支持图片识别。', en: 'Click **Add model** to fill: name, protocol (OpenAI / Anthropic), endpoint, key, model name, whether image recognition is supported.' },
  'tour.aiProfileCallout': { zh: '密钥只存在你本机；接口地址填错会「测试」失败，先测通再用。', en: 'The key is stored only on your machine; a wrong endpoint fails the test, so test it successfully before using.' },
  'tour.aiConfigTitle': { zh: '智能助手 · 上游配置（齿轮）', en: 'AI Assistant · upstream config (gear)' },
  'tour.aiConfigBody1': { zh: '顶栏右上角这个**齿轮**是 **AI 上游配置**：在这里添加并管理你的**模型服务**（OpenAI / Anthropic 两种协议）。', en: 'The **gear** at top-right of the top bar is the **AI upstream config**: add and manage your **model services** here (OpenAI / Anthropic protocols).' },
  'tour.aiConfigBody2': { zh: '至少要有一个模型服务，智能助手才能用。下一步我直接帮你打开它。', en: 'You need at least one model service for the assistant to work. Next I will open it for you.' },
  'tour.aiListTitle': { zh: '智能助手 · 会话列表', en: 'AI Assistant · session list' },
  'tour.aiListBody1': { zh: '这一片就是会话列表。**点任意一行**进入那轮对话；正在执行的会话标题旁边会有小转圈，上次出错的会有一个红点。', en: 'This area is the session list. **Click any row** to enter that conversation; a running session shows a small spinner by its title, a failed one a red dot.' },
  'tour.aiListBody2': { zh: '要真正用起来，还得有一个**模型服务**——下一步就讲顶栏那个齿轮怎么配。', en: 'To really use it you also need a **model service** — next I cover the top-bar gear.' },
  'tour.aiNewTitle': { zh: '智能助手 · 新建会话', en: 'AI Assistant · new session' },
  'tour.aiNewBody1': { zh: '进来是**会话列表**。右上角这个 **新建会话** 就是开一轮新对话——每次想换个话题、换个任务，就新建一个，历史不会被冲掉。', en: 'You enter the **session list**. The **New session** at top-right starts a fresh conversation — start a new one whenever you switch topic or task; history is not overwritten.' },
  'tour.aiNewBody2': { zh: '列表里每一行是一个会话：显示标题、最后活动时间；鼠标移上去会出现**重命名**和**删除**两个小按钮。', en: 'Each row is a session: shows title and last activity time; hovering shows **Rename** and **Delete** small buttons.' },
  'tour.navAiTitle': { zh: '下一站 · 智能助手', en: 'Next · AI Assistant' },
  'tour.navAiBody1': { zh: '再往下是 **智能助手**：一个内置在咔咔珂里的 AI 对话界面。', en: 'Further down is the **AI Assistant**: a built-in AI chat UI inside Kakake.' },
  'tour.navAiBody2': { zh: '接上你自己的大模型服务，就能在这里直接问问题、让它帮忙看代码 / 改文件。', en: 'Connect your own model service and you can ask questions directly, or have it read code / edit files.' },
  'tour.navAiBody3': { zh: '点它进去看看怎么用。', en: 'Click to see how.' },
  'tour.opDetailActionsTitle': { zh: '账号详情 · 底部操作', en: 'Account detail · bottom actions' },
  'tour.opDetailActionsBody1': { zh: '最底下一排是操作：**刷新资料**（重新拉腾讯那边的资料）、**启用 / 停用**（临时让这个机器人下线，不用删掉它）、**删除**（把账号从咔咔珂移除，会先弹确认）。', en: 'The bottom row: **Refresh profile** (re-pull Tencent profile), **Enable / Disable** (temporarily take this bot offline without deleting), **Delete** (remove the account from Kakake, with a confirm first).' },
  'tour.opDetailActionsBody2': { zh: '未接入的账号这里显示的是「补密钥并接入」。', en: 'A "not connected" account shows "fill secret and connect" here.' },
  'tour.opDetailInsightTitle': { zh: '账号详情 · 官方接口数据 / 交互配置', en: 'Account detail · official API data / interaction config' },
  'tour.opDetailInsightBody1': { zh: '**官方接口数据**：拉取并显示机器人在腾讯那边的资料（头像、简介、WSS 网关接入点、Token 剩余时间），还能展开看它**加入了哪些频道**、频道里有哪些子频道。点「重新拉取」可手动刷新。', en: '**Official API data**: fetch and show the bot’s profile on Tencent’s side (avatar, intro, WSS gateway endpoint, Token remaining time), and expand to see **which channels it joined** and their sub-channels. Click "Re-fetch" to refresh manually.' },
  'tour.opDetailInsightBody2': { zh: '**交互配置**：给这个机器人配自定义菜单、指令面板等交互入口，各自在独立窗口里编辑。', en: '**Interaction config**: set custom menus, command panels, etc. for this bot, each edited in its own window.' },
  'tour.opDetailInsightCallout': { zh: '这两块要填了 AppSecret 才有数据；只登记 AppID 的「未接入」账号拉不到。', en: 'These two sections only show data after AppSecret is filled; accounts registered with AppID only and marked unconnected cannot fetch anything.' },
  'tour.opDetailDauTitle': { zh: '账号详情 · 日活（DAU）', en: 'Account detail · DAU' },
  'tour.opDetailDauBody1': { zh: '**日活**：今日 / 昨日 / 近 7 天 / 累计四个数字，下面还有一张走势小图。', en: '**DAU**: today / yesterday / last 7 days / total four numbers, plus a small trend chart below.' },
  'tour.opDetailDauBody2': { zh: '这数据是腾讯官方接口给的，能看出这个机器人到底有没有人在用、用得怎么样。', en: 'This data comes from Tencent’s official API — shows whether anyone is actually using this bot and how.' },
  'tour.opDetailTitle': { zh: '账号详情 · 概览', en: 'Account detail · overview' },
  'tour.opDetailBody1': { zh: '这就是账号详情。最上面是**头像、名称、AppID**，下面一行标明 **正式 / 沙箱环境** 与接入方式（HTTPS Webhook 或 WebSocket 网关），再下面一排是**连接状态**。', en: 'This is the account detail. Top is **avatar, name, AppID**, a line below marking **official / sandbox environment** and connection method (HTTPS Webhook or WebSocket gateway), then a row of **connection status**.' },
  'tour.opDetailBody2': { zh: '右上角 × 关闭。往下滚，还有日活与官方数据。', en: 'Close with × top-right. Scroll down for DAU and official data.' },
  'tour.opCardTitle': { zh: '开放平台 · 账号卡片', en: 'Open Platform · account card' },
  'tour.opCardBody1': { zh: '每张卡片是一个官方机器人账号：**头像 + 名称 + AppID**，右上角小圆点绿色表示在线，右上角的标签区分 **正式 / 沙箱 / 未接入**。', en: 'Each card is one official bot account: **avatar + name + AppID**, a green dot top-right means online, and a top-right tag marks **official / sandbox / not connected**.' },
  'tour.opCardBody2': { zh: '已接入的卡片下面还有四个日活小格：**今日 / 昨日 / 近7天 / 累计**。', en: 'Connected cards also show four DAU cells below: **today / yesterday / last 7 days / total**.' },
  'tour.opCardBody3': { zh: '下一步我直接帮你点开一张卡片，看看详情里有什么。', en: 'Next I will open a card for you to see the details.' },
  'tour.opAddTitle': { zh: '开放平台 · 手动添加账号', en: 'Open Platform · add account manually' },
  'tour.opAddBody1': { zh: '不想扫码也能加：点这个 **添加账号**。', en: 'Do not want to scan? Click this **Add account**.' },
  'tour.opAddBody2': { zh: '**只填 AppID** = 先登记为「未接入」（占位，之后可以补）；**同时填 AppSecret** = 直接创建连接并接入咔咔珂。', en: '**AppID only** = register as "not connected" (placeholder, fill later); **AppID + AppSecret** = create and connect to Kakake directly.' },
  'tour.opAddBody3': { zh: '已经在腾讯开放平台建好的机器人，用这条路径最省事。', en: 'For bots already created on Tencent’s open platform, this path is easiest.' },
  'tour.opStatsTitle': { zh: '开放平台 · 三个数字', en: 'Open Platform · three numbers' },
  'tour.opStatsBody1': { zh: '下面这一排是三个总览数字：**机器人账号**（一共接了几个）、**连接中**（此刻在线几个，绿色）、**今日日活**（今天有多少用户跟这些机器人互动过）。', en: 'The row below is three overview numbers: **bot accounts** (how many connected), **connecting** (how many online now, green), **today DAU** (how many users interacted with these bots today).' },
  'tour.opStatsBody2': { zh: '一眼就能看出官方机器人整体跑没跑起来。', en: 'A glance tells you whether the official bots are running at all.' },
  'tour.opLoginTitle': { zh: '开放平台 · 扫码接入（这页是干嘛的）', en: 'Open Platform · scan to connect (what this page is)' },
  'tour.opLoginBody1': { zh: '先说清楚这一页**是干嘛的**：它管的是**腾讯 QQ 官方机器人**（q.qq.com 那条官方通道），不是 NapCat 那种。', en: 'First, what this page **is for**: it manages **Tencent QQ official bots** (the q.qq.com official channel), not NapCat-style ones.' },
  'tour.opLoginBody2': { zh: '**扫码登录的用途**：点「扫码接入」，用**手机 QQ 扫**一下，咔咔珂会自动取回这个机器人的 **AppID 与密钥**并完成接入——**不用你去开放平台申请开发者账号，也不用手动抄密钥**。扫完这个机器人就登记在这里了，并且会自动成为一条「QQ 官方」连接，之后插件就能在它上面跑。', en: '**Use of scan login**: click "Scan to connect", scan with **phone QQ**, and Kakake auto-retrieves this bot’s **AppID and secret** and completes connection — **no applying for a developer account, no hand-copying secrets**. After scanning, the bot is registered here and auto-becomes a "QQ official" connection, so plugins can run on it.' },
  'tour.opLoginBody3': { zh: '所以这页和「连接」页的分工是：**连接页是手动填参数**，**这里是扫码免填**。已经用官方通道接进来的机器人，来这一页管最方便。', en: 'So the split with the Connections page is: **Connections = manually fill params**, **here = scan, no filling**. Bots already connected via the official channel are easiest managed here.' },
  'tour.opLoginBody4': { zh: '一个二维码 = 一个机器人；想接多个就再扫一次，接完这里会显示已绑定的 AppID 和来源 IP。', en: 'One QR = one bot; scan again for more; after connecting it shows the bound AppID and source IP.' },
  'tour.opLoginCallout': { zh: '必须用 QQ 内置相机直接扫，长按识别 / 相册截图都不行。扫的是腾讯官方通道，咔咔珂不会经手你的 QQ 密码。', en: 'You must scan with the QQ in-app camera directly; long-press recognition or album screenshots will not work. It uses Tencent official channel, and Kakake never touches your QQ password.' },
  'tour.navOpenPlatformTitle': { zh: '下一站 · 开放平台', en: 'Next · Open Platform' },
  'tour.navOpenPlatformBody1': { zh: '再往下是 **开放平台**，专门管**腾讯 QQ 官方机器人**的账号。', en: 'Further down is the **Open Platform**, which manages **Tencent QQ official bot** accounts.' },
  'tour.navOpenPlatformBody2': { zh: '和「连接」页不同：这里走的是腾讯官方扫码通道，不用自己申请开发者账号、不用手填密钥。', en: 'Unlike the Connections page: it uses Tencent’s official scan channel — no applying for a developer account, no hand-typing secrets.' },
  'tour.navOpenPlatformBody3': { zh: '点它进去看看。', en: 'Click to look.' },
  'tour.toolPluginDevTitle': { zh: '工具 ③ 插件开发', en: 'Tool ③ plugin development' },
  'tour.toolPluginDevBody1': { zh: '**插件开发**：总览 + 五条轨的教程与示例代码——OneBot 的 **TS（构建式）/ JS ESM / JS CJS**、**QQ 官方（GF-）**、**双生（sssx-）**。', en: '**Plugin development**: overview + tutorials and samples for five tracks — OneBot **TS (build) / JS ESM / JS CJS**, **QQ official (GF-)**, **Twin (sssx-)**.' },
  'tour.toolPluginDevBody2': { zh: '想自己写插件从这里起步：先读总览，再按你要接的机器人类型挑一条轨。', en: 'Start here to write your own plugin: read the overview, then pick a track by the bot type you target.' },
  'tour.toolImageObfTitle': { zh: '工具 ④ 图片混淆', en: 'Tool ④ image obfuscation' },
  'tour.toolImageObfBody1': { zh: '**图片混淆**：把图片按你选的路线打乱或加密——**AES 字节加密**、**像素置乱**等多条路线可选，任意图片格式都能处理。', en: '**Image obfuscation**: scramble or encrypt an image along the route you pick — **AES byte encryption**, **pixel shuffle**, and more; any image format works.' },
  'tour.toolImageObfBody2': { zh: '设了密码就必须拿同一个密码才能还原，适合把不想被直接看到的图发出去；**免密码**模式只是打乱、不具保密性，任何人都能还原。', en: 'With a password set, only the same password restores it — handy for sharing images you would rather not show outright. **No-password** mode only scrambles; anyone can restore it, so it is not confidential.' },
  'tour.toolImageObfCallout': { zh: '密码一旦忘了就还原不回来，别拿唯一一份原图去试手。', en: 'A forgotten password means the image cannot be restored — never test this on your only copy.' },
  'tour.toolImageEditTitle': { zh: '工具 ⑤ 图片工具箱', en: 'Tool ⑤ image toolbox' },
  'tour.toolImageEditBody1': { zh: '**图片工具箱**：改分辨率、裁剪、加圆角、压缩体积、转换格式（**PNG / JPEG / WebP**）。', en: '**Image toolbox**: resize, crop, round corners, shrink size, convert format (**PNG / JPEG / WebP**).' },
  'tour.toolImageEditBody2': { zh: '支持**批量**处理，也能指定「目标体积」让它自动逼近——做头像、压图发给别人时省得来回试参数。', en: 'It handles **batches**, and you can set a **target size** it will tune toward — no more trial and error when making avatars or shrinking images to send.' },
  'tour.toolMediaTitle': { zh: '工具 ② 视频解析', en: 'Tool ② media parsing' },
  'tour.toolMediaBody1': { zh: '**视频解析**：粘贴 B站 / 抖音 / 小红书 / 快手 / TikTok / YouTube / X / Telegram 链接。', en: '**Media parsing**: paste Bilibili / Douyin / Xiaohongshu / Kuaishou / TikTok / YouTube / X / Telegram links.' },
  'tour.toolMediaBody2': { zh: '解析出标题、封面与直链，方便做下载或转发类插件时取素材。整段分享文案粘进去也认，会自动从里面挖出链接。', en: 'It parses title, cover, and direct link — handy for grabbing material when writing download/forward plugins. Pasting the whole share text also works; it digs the link out.' },
  'tour.toolEncodeTitle': { zh: '工具 ① 常用编码转换', en: 'Tool ① common encoding conversion' },
  'tour.toolEncodeBody1': { zh: '**常用编码转换**：Base64 / Hex / URL / Unicode / 进制 / gzip 等互转。', en: '**Common encoding conversion**: Base64 / Hex / URL / Unicode / base / gzip etc. inter-conversion.' },
  'tour.toolEncodeBody2': { zh: '纯本地计算、不联网，粘进去即得结果，做插件时拼报文、解回调很好用。', en: 'Pure local compute, no network; paste in and get the result — handy for crafting payloads or decoding callbacks when writing plugins.' },
  'tour.toolsTitle': { zh: '工具箱总览', en: 'Toolbox overview' },
  'tour.toolsBody1': { zh: '「工具」页就是这几张卡片，点任意一张进入对应工具。', en: 'The "Tools" page is just these cards; click any to enter that tool.' },
  'tour.toolsBody2': { zh: '下面我按顺序把它讲完——**先讲完工具箱里的三样**，再往下走别的界面。', en: 'I will finish them in order — **the three in the toolbox first**, then move to other screens.' },
  'tour.navToolsTitle': { zh: '下一站 · 实用工具', en: 'Next · handy tools' },
  'tour.navToolsBody1': { zh: '侧边栏从上往下第六个是 **实用工具**，点它进入工具箱。', en: 'The sixth from the top in the sidebar is **Handy Tools**; click to enter the toolbox.' },
  'tour.navToolsBody2': { zh: '里面是几样调试 / 日常会用到的小工具，下面一张一张带你看。', en: 'A few debugging / daily-use gadgets inside; I will show them one by one.' },
  'tour.storeRefreshTitle': { zh: '顶栏 ④ 强制刷新', en: 'Top bar ④ force refresh' },
  'tour.storeRefreshBody1': { zh: '最后一个是**刷新**，而且是**强制刷新**：清掉缓存、重新拉一遍最新列表，期间会有「正在刷新资源」的提示。', en: 'The last is **refresh**, and a **force refresh**: clear cache and re-pull the latest list, with a "Refreshing resources" hint.' },
  'tour.storeRefreshBody2': { zh: '源站刚上了新插件、但你这还看不到的时候，点它就对了。', en: 'When the source just published a new plugin but you do not see it, click it.' },
  'tour.storeRefreshCallout': { zh: '强制刷新不会清掉你选的分类和排序，放心点。', en: 'A forced refresh will not clear your chosen category and sort order, so click it without worry.' },
  'tour.storeSortTitle': { zh: '顶栏 ③ 排序方式', en: 'Top bar ③ sort order' },
  'tour.storeSortBody1': { zh: '第三个是**排序**。它点开之后有哪些选项，**会跟着你用的资源来源变**：', en: 'The third is **sort**. Its options **change with your resource source**:' },
  'tour.storeSortBody2': { zh: '**GitHub 源**可按 **星标数 / 更新时间 / 作者作品数** 排；**咔咔珂官方源**则是浏览、下载等维度。', en: '**GitHub source** can sort by **stars / update time / author work count**; the **Kakake official source** by views, downloads, etc.' },
  'tour.storeSortBody3': { zh: '想找热门就按星标 / 下载排，想找新出的就按更新时间排。', en: 'Want popular? Sort by stars / downloads. Want newest? Sort by update time.' },
  'tour.storeSortCallout': { zh: '排序和分类可以同时用：先筛分类缩小范围，再排序把最想要的顶到前面。', en: 'Sorting and filtering can be combined: narrow by category first, then sort to bring what you want to the top.' },
  'tour.storePaginationTitle': { zh: '列表底部 · 翻页', en: 'List bottom · paging' },
  'tour.storePaginationBody1': { zh: '资源多于一页时，底部会出现这条**翻页条**：左右箭头翻前后页，中间直接点页码。', en: 'When resources exceed one page, this **paging bar** appears at the bottom: left/right arrows for prev/next, click a page number in the middle.' },
  'tour.storePaginationBody2': { zh: '页数超过 5 页时还会多出**跳页输入框 + Go**，输入页码回车即可直达。', en: 'Beyond 5 pages a **jump input + Go** appears; type a page number and Enter to jump.' },
  'tour.storePaginationCallout': { zh: '翻页只影响「看」，不影响已经装好的插件。', en: 'Paging only affects what you see, not the plugins already installed.' },
  'tour.storeDetailInstallTitle': { zh: '详情 · 在这里安装', en: 'Detail · install here' },
  'tour.storeDetailInstallBody1': { zh: '弹窗底部同样有**安装 / 更新**按钮，和卡片上那个是同一件事——看清楚简介、版本要求、文档之后再决定装不装，比较稳。', en: 'The bottom of the popup also has an **install / update** button, same as the card one — decide after reading the intro, version requirement, and docs; safer that way.' },
  'tour.storeDetailInstallBody2': { zh: '左边「关闭」可以退出弹窗。', en: '**Close** on the left exits the popup.' },
  'tour.storeDetailInfoTitle': { zh: '详情 · 插件信息与文档', en: 'Detail · plugin info & docs' },
  'tour.storeDetailInfoBody1': { zh: '再往下是**插件信息**：当前装的是哪个版本、有没有可更新、**最低版本要求**（你的咔咔珂版本不够会标红提醒）、GitHub 源还有**仓库星数**。', en: 'Further down is **plugin info**: which version is installed, whether an update exists, the **minimum version required** (red if your Kakake is too old), and for GitHub source the **repo stars**.' },
  'tour.storeDetailInfoBody2': { zh: '有文档的会接一段**文档**（GitHub 源直接渲染仓库 README）；咔咔珂源的卡片下面则是**评论**区，可以看看别人用了怎么说（只能看，不能发）。', en: 'If docs exist, a **docs** section follows (GitHub source renders the repo README); the Kakake source card has a **comments** area where you can read others’ opinions (view only, no posting).' },
  'tour.storeDetailInfoCallout': { zh: '「当前版本偏低」时先去更新咔咔珂再装，否则插件可能跑不起来。', en: 'When it says the current version is too low, update Kakake first and then install, otherwise the plugin may fail to run.' },
  'tour.storeDetailIntroTitle': { zh: '详情 · 简介与版本标签', en: 'Detail · intro & version tags' },
  'tour.storeDetailIntroBody1': { zh: '**简介**是作者写的完整介绍（列表卡片上只有两行，这里能看全）。', en: '**Intro** is the author’s full description (the list card shows only two lines; here you see all).' },
  'tour.storeDetailIntroBody2': { zh: '紧跟着是**版本号 + 标签**，用来确认这个资源做什么、适配哪些场景。', en: 'Right after is **version + tags**, to confirm what this resource does and which scenarios it fits.' },
  'tour.storeDetailTitle': { zh: '详情弹窗 · 头部', en: 'Detail popup · header' },
  'tour.storeDetailBody1': { zh: '点卡片就进到这个**详情弹窗**。最上面是**头像 + 标题 + 作者 / 版本 / 上传人**；GitHub 源的头像是可点的，直接跳到作者主页。', en: 'Clicking a card opens this **detail popup**. Top is **avatar + title + author / version / uploader**; the GitHub source avatar is clickable, jumping to the author’s page.' },
  'tour.storeDetailBody2': { zh: '右上角 × 关闭。下面我把弹窗里每一块讲一遍。', en: 'Close with × at top-right. I will go through each block below.' },
  'tour.storeInstallTitle': { zh: '资源卡片 · 一键安装', en: 'Resource card · one-click install' },
  'tour.storeInstallBody1': { zh: '卡片底部这个按钮就是**安装 / 更新**：没装过显示「安装」，装过但源上有新版就变成「更新」，已是最新则显示灰色的「已安装」。', en: 'The button at the bottom of the card is **install / update**: "Install" if never installed, "Update" if the source has a newer version, grey "Installed" if already latest.' },
  'tour.storeInstallBody2': { zh: '装的时候会有进度气泡，装完直接进插件页——但**还没生效**：仍要回「插件」页开总开关、再到连接里勾选，也就是前面讲的两道开关。', en: 'A progress bubble appears while installing, then it jumps to the Plugins page — but it is **not yet active**: you still must go to the Plugins page to flip the master switch and tick it in the connection, i.e. the two switches from before.' },
  'tour.storeInstallBody3': { zh: '灰色不可点的按钮说明这个资源**不允许下载**（鼠标悬停会给出原因）。', en: 'A grey unclickable button means this resource is **not downloadable** (hover for the reason).' },
  'tour.storeInstallCallout': { zh: 'GitHub 源的资源安装前会先弹一份风险声明（第三方投稿，自行甄别），确认后才会开始下载。', en: 'For GitHub sources a risk notice (third-party submissions, judge them yourself) appears before install, and the download starts only after you confirm.' },
  'tour.storeCardTitle': { zh: '资源卡片 · 每张讲了什么', en: 'Resource card · what each shows' },
  'tour.storeCardBody1': { zh: '每张卡片从上到下：**版本号**（右上角）、**头像 + 标题 + 作者**（作者名后面那个小色块是**类型角标**，五档各一种颜色）、**简介**（最多两行）、**下载次数 + 标签**。**点卡片任意位置**看详情。', en: 'Each card top to bottom: **version** (top-right), **avatar + title + author** (the small color block after the author is the **type badge**, one color per category), **intro** (up to two lines), **downloads + tags**. **Click anywhere on the card** for details.' },
  'tour.storeCardBody2': { zh: '列表一次最多 **16 个**，超出就翻页——下面会讲。', en: 'The list shows at most **16** at once; more means paging — covered below.' },
  'tour.storeGridTitle': { zh: '资源列表 · 一页 16 个', en: 'Resource list · 16 per page' },
  'tour.storeGridBody1': { zh: '这一片就是资源列表，每页最多 **16 个**。', en: 'This area is the resource list, up to **16** per page.' },
  'tour.storeGridBody2': { zh: '顺便说下刚才那个筛选：想恢复全部，点一下已经选中的分类即可取消（下面为了把完整列表讲清楚，我已经帮你取消筛选了）。', en: 'About that filter: to restore all, click the selected category to cancel (below I already cancelled it for you to explain the full list).' },
  'tour.storeCategoryPickedTitle': { zh: '分类筛选 · 选好之后', en: 'Category filter · after picking' },
  'tour.storeCategoryPickedBody1': { zh: '看这里——按钮上的图标已经变成了**「官方」两个字**，一眼就知道现在筛的是哪一档。', en: 'Look — the icon on the button has become the two characters **"Official"**, so you know at a glance which category is filtered.' },
  'tour.storeCategoryPickedBody2': { zh: '下面这个就是**筛选后的列表**：只剩这一类的资源了。想换一档就再点按钮重选；想看全部，再点一次当前这项即可取消。', en: 'Below is the **filtered list**: only that kind remains. Pick another category to re-filter; to see all, click the current one again to cancel.' },
  'tour.storeCategoryPickedBody3': { zh: '万一这一类暂时没有资源，列表位置会显示「该分类下暂无资源」——不是坏了，是这一类真的空着。', en: 'If this category is temporarily empty, the list shows "No resources in this category" — not broken, just truly empty.' },
  'tour.storeCategoryMenuTitle': { zh: '分类筛选 · 展开后的五档', en: 'Category filter · the five options' },
  'tour.storeCategoryMenuBody1': { zh: '这就是点开后的分类列表，一共五档：', en: 'This is the category list after opening; five options total:' },
  'tour.storeCategoryMenuBody2': { zh: '**野鸡**（第三方 / 野生插件）、**官方**（咔咔珂官方出品）、**双生**（`sssx-plugin-` 开头，一份代码同时跑 OneBot 与 QQ 官方两条协议）、**微信**、**其他**（KOOK 等）。', en: '**Wild** (third-party / wild plugins), **Official** (Kakake official), **Twin** (`sssx-plugin-` prefix, one codebase for both OneBot and QQ official), **WeChat**, **Other** (KOOK, etc.).' },
  'tour.storeCategoryMenuBody3': { zh: '选中哪一项，前面的**对勾**就落在哪一项上；**再点一次已选中的那项就是取消**，回到全部。', en: 'Whichever you pick, the **check** lands on it; **click the selected one again to cancel** back to all.' },
  'tour.storeCategoryMenuBody4': { zh: '下面我直接帮你选「官方」这一档，看看列表会变成什么样。', en: 'Next I will pick "Official" for you to see how the list changes.' },
  'tour.storeCategoryMenuCallout': { zh: '分类是「一次性」的：刷新网页或切走界面就自动清空；但停在本页安装 / 更新 / 刷新资源都不会丢。', en: 'Category is "one-shot": refreshing the page or leaving the screen clears it; but staying on this page to install / update / refresh resources keeps it.' },
  'tour.storeCategoryTitle': { zh: '顶栏 ② 分类筛选（按钮本身）', en: 'Top bar ② category filter (the button)' },
  'tour.storeCategoryBody1': { zh: '第二个是**分类筛选**。**还没选**的时候它显示一个**标签图标**；选定某一档之后，图标会直接变成那两个字的名字。', en: 'The second is the **category filter**. When **nothing is selected** it shows a **tag icon**; once a category is picked, the icon turns into those two characters of the name.' },
  'tour.storeCategoryBody2': { zh: '也就是说：看按钮上是图标还是文字，就知道现在有没有在筛选。', en: 'So: looking at the button tells you whether a filter is active.' },
  'tour.storeCategoryBody3': { zh: '下一步我直接帮你把它点开，看看里面能选什么。', en: 'Next I will open it for you to see what is inside.' },
  'tour.storeOriginTitle': { zh: '顶栏 ① 打开当前资源来源', en: 'Top bar ① open current resource source' },
  'tour.storeOriginBody1': { zh: '最左边这个**外链图标**是「打开当前资源来源」：在新标签页打开你现在用的这个源站。', en: 'The leftmost **external-link icon** is "open current resource source": open the source site you are using in a new tab.' },
  'tour.storeOriginBody2': { zh: '当前是**咔咔珂官方源**还是 **GitHub 社区源**，由「设置 → 资源来源」决定（后面设置页会讲）。', en: 'Whether it is the **Kakake official source** or the **GitHub community source** is set under "Settings → Resource source" (covered on the Settings page later).' },
  'tour.storeOriginBody3': { zh: '想看看源站上还有没有别的东西、或者去仓库看源码，点它最省事。', en: 'Want to see what else is on the source, or read the repo — click it.' },
  'tour.storeSearchTitle': { zh: '顶栏下方 · 搜索框', en: 'Below top bar · search box' },
  'tour.storeSearchBody1': { zh: '**搜索框**按**标题 / 作者 / 标签**匹配，边打边过滤，不用回车。', en: 'The **search box** matches by **title / author / tag**, filtering as you type, no Enter needed.' },
  'tour.storeSearchBody2': { zh: '记得住插件名的时候它最快；记不住就用下面的分类筛选慢慢挑。', en: 'Fastest when you remember the plugin name; if not, use the category filter below.' },
  'tour.storeToolbarTitle': { zh: '资源 · 先看这一条搜索栏', en: 'Resources · start with this search bar' },
  'tour.storeToolbarBody1': { zh: '进到资源页，顶栏下面这条就是**搜索栏**，只用来找东西。', en: 'Entering Resources, the bar under the top bar is the **search bar**, only for finding things.' },
  'tour.storeToolbarBody2': { zh: '资源页的操作按钮全部在**顶栏右侧**（来源 / 分类 / 排序 / 刷新），下面我带你一个一个看过去。', en: 'All resource page action buttons are at the **top-right of the top bar** (source / category / sort / refresh) — I will walk through them one by one.' },
  'tour.navPluginStoreTitle': { zh: '资源商店', en: 'Resource store' },
  'tour.navPluginStoreBody1': { zh: '不想自己找插件？**资源** 页是在线插件商店。', en: 'Do not want to find plugins yourself? The **Resources** page is the online plugin store.' },
  'tour.navPluginStoreBody2': { zh: '可以**浏览**在线资源、看**简介与文档**、**一键安装**到本地——装完同样要按上一步的「两道开关」启用。', en: 'You can **browse** online resources, see **intro & docs**, **one-click install** locally — and still enable via the "two switches" from the previous step.' },
  'tour.pluginsCardActionsTitle': { zh: '卡片 · 底部操作按钮', en: 'Card · bottom action buttons' },
  'tour.pluginsCardActionsBody1': { zh: '卡片底部一排按钮：**说明**（查看插件文档，有文档才显示）、**打开控制台**（插件自带的管理页，需先加载成功才有）、**删除**（移除安装目录，可选是否一并清数据）。', en: 'The bottom row: **Docs** (view plugin docs, shown only if docs exist), **Open console** (the plugin’s own admin page, only after it loads successfully), **Delete** (remove install dir, optionally with data).' },
  'tour.pluginsCardActionsBody2': { zh: '左下角还有**类型 / 作者**标签，方便一眼分辨插件来源。', en: 'Bottom-left also has **type / author** tags to tell the source at a glance.' },
  'tour.pluginMasterSwitchTitle': { zh: '卡片 · 总开关（第一道开关）', en: 'Card · master switch (first switch)' },
  'tour.pluginMasterSwitchBody1': { zh: '卡片右上角这个开关是插件的 **全局总开关**。', en: 'The switch at the top-right of the card is the plugin’s **global master switch**.' },
  'tour.pluginMasterSwitchBody2': { zh: '打开它只是「全局层面允许」——还得回连接页为具体账号勾选启用（第二道开关），插件才会真的加载运行。', en: 'Turning it on only "allows globally" — you must still go to Connections and tick-enable it for a specific account (second switch) for it to actually load.' },
  'tour.pluginMasterSwitchCallout': { zh: '旁边的状态徽标：运行中 / 停止 / 错误；报错时卡片上会显示红色错误原因。', en: 'The status badge beside it shows Running / Stopped / Error; on failure the card displays the red error reason.' },
  'tour.pluginsCardTitle': { zh: '插件卡片总览', en: 'Plugin card overview' },
  'tour.pluginsCardBody1': { zh: '每张卡片就是一个已安装的插件：左上角**图标 / 名称 / 版本号**，右上角**状态徽标 + 总开关**，底部还有一排操作按钮。', en: 'Each card is one installed plugin: top-left **icon / name / version**, top-right **status badge + master switch**, and a row of action buttons at the bottom.' },
  'tour.pluginsCardBody2': { zh: '下一步先带你看最关键的「总开关」。', en: 'Next I will show you the most important "master switch".' },
  'tour.pluginsRefreshTitle': { zh: '工具栏 · 刷新', en: 'Toolbar · refresh' },
  'tour.pluginsRefreshBody1': { zh: '**刷新**：重新扫描本地插件目录。', en: '**Refresh**: re-scan the local plugin directory.' },
  'tour.pluginsRefreshBody2': { zh: '装完 / 删完插件后列表若没立刻变化，点一下它多半就同步过来了。', en: 'If the list does not update right after installing / deleting a plugin, clicking it usually syncs.' },
  'tour.pluginsUploadTitle': { zh: '工具栏 · 上传 zip', en: 'Toolbar · upload zip' },
  'tour.pluginsUploadBody1': { zh: '**上传 zip**：安装本地插件压缩包。点它选文件，或直接把压缩包**拖进页面**——会先弹出队列让你确认后再上传。', en: '**Upload zip**: install a local plugin archive. Click to choose a file, or drag the archive **into the page** — a queue pops up to confirm before uploading.' },
  'tour.pluginsUploadBody2': { zh: '支持 zip / tar / gz / rar / 7z 等常见格式。', en: 'Supports zip / tar / gz / rar / 7z and common formats.' },
  'tour.pluginsToolbarTitle': { zh: '插件页 · 搜索框与顶栏操作', en: 'Plugins page · search box & top-bar actions' },
  'tour.pluginsToolbarBody1': { zh: '这里是插件页的**搜索框**，按名称 / 作者过滤插件。', en: 'This is the plugin page **search box**, filtering by name / author.' },
  'tour.pluginsToolbarBody2': { zh: '「上传 zip」「刷新」这两个按钮已经移到**顶栏右侧**了——顶栏会跟着当前界面显示它对应的操作按钮。', en: 'The "Upload zip" and "Refresh" buttons moved to the **top-right of the top bar** — the top bar shows the actions for the current screen.' },
  'tour.pluginsToolbarBody3': { zh: '下面把这两个按钮分开一个一个讲。', en: 'Next I will cover these two buttons one by one.' },
  'tour.pluginsFilterTitle': { zh: '筛选与搜索插件', en: 'Filter & search plugins' },
  'tour.pluginsFilterBody1': { zh: '这排标签按来源过滤：**全部 / 三方（OneBot）/ 官方 / 双生 / 微信 / KOOK**。', en: 'This row of tags filters by source: **All / Third-party (OneBot) / Official / Twin / WeChat / KOOK**.' },
  'tour.pluginsFilterBody2': { zh: '**双生**是目录名 `sssx-plugin-` 开头那一类：一份代码同时挂在 OneBot 和 QQ 官方两条协议上，两边都要各开一次开关。', en: '**Twin** is the `sssx-plugin-` directory prefix: one codebase serving both OneBot and QQ official, each needing its switch toggled once.' },
  'tour.pluginsFilterBody3': { zh: '上面的搜索框可以按 **插件名或 ID** 快速查找。装了很多插件时很好用。', en: 'The search box above finds by **plugin name or ID** — handy with many plugins.' },
  'tour.pluginsStatsTitle': { zh: '插件的两道开关（最容易绕晕）', en: 'The two plugin switches (most confusing)' },
  'tour.pluginsStatsBody1': { zh: '① 在这个「插件」页，把插件卡片右上角的 **总开关** 打开——这是全局层面的启用。', en: '① On this "Plugins" page, turn on the **master switch** at the top-right of the plugin card — that is the global enable.' },
  'tour.pluginsStatsBody2': { zh: '② 再回到 **连接** 页 → 点开对应连接 → 进 **插件管理** → 为这个机器人账号**也勾选启用**这个插件。', en: '② Then go back to **Connections** → open the connection → **Plugin management** → also tick-enable this plugin for that bot account.' },
  'tour.pluginsStatsCallout': { zh: '两处都开，插件才真正在该账号上加载运行；只开一处 = 不生效！这也是新手最常见的坑。', en: 'Both on, and the plugin truly loads on that account; only one on = no effect! This is the most common beginner trap.' },
  'tour.navPluginsTitle': { zh: '第二步 · 插件', en: 'Step 2 · Plugins' },
  'tour.navPluginsBody1': { zh: '**插件** 页是全局插件库：安装、卸载、查看说明都在这里。', en: 'The **Plugins** page is the global plugin library: install, uninstall, and read docs.' },
  'tour.navPluginsBody2': { zh: '点进去看看。', en: 'Click in to look.' },
  'tour.connectionsImportTitle': { zh: '顶栏 · 导入连接配置', en: 'Top bar · import connection config' },
  'tour.connectionsImportBody1': { zh: '旁边这个**文件图标**才是**导入**（和导出是两个按钮，别点错）。选一份之前导出的 json 即可导回来。', en: 'The **file icon** next to it is **import** (two separate buttons — do not mix them up). Pick a previously exported json to bring it back.' },
  'tour.connectionsImportBody2': { zh: '**导入既是叠加也是覆盖**：认得出来的那条就覆盖，认不出来的就当新的加进来，不会动到其它连接。', en: '**Import is both additive and overwriting**: recognized entries are overwritten, unrecognized ones are added as new; other connections are untouched.' },
  'tour.connectionsImportBody3': { zh: '**OneBot 认四个要素：账号 + 地址 + 端口 + 密钥**，四个都一样才算同一条；只同账号但换了端口，那是另一个接入点，会作为新连接加进来。官方 / KOOK / 微信则按账号认。', en: 'OneBot matches on four factors: **account + address + port + secret** — all four identical counts as the same one; same account but different port is a different endpoint and is added as new. Official / KOOK / WeChat match by account.' },
  'tour.connectionsImportBody4': { zh: '除了点按钮，**直接把 json 文件拖进界面**也能导入（界面上任意位置都接得住），只认 .json，语法不对会直接判失败。', en: 'Besides the button, you can also **drag the json file into the page** anywhere — only .json is accepted, bad syntax fails outright.' },
  'tour.connectionsImportCallout': { zh: '插件开关是合并的：文件里写了的以它为准，没写到的保持原样——不会因为导入把原本开着的插件关掉。', en: 'Plugin switches are merged: what the file specifies wins, unspecified ones stay as-is — importing will not turn off a plugin that was on.' },
  'tour.connectionsExportTitle': { zh: '顶栏 · 导出连接配置', en: 'Top bar · export connection config' },
  'tour.connectionsExportBody1': { zh: '顶栏这个**分享图标**就是**导出**：把整套连接配置——连同每条连接开了哪些插件——存成一份 json 下载下来。', en: 'This **share icon** in the top bar is **export**: save the whole connection config — including which plugins each connection has — as a json download.' },
  'tour.connectionsExportBody2': { zh: '换机器、重装、或者想给别人一套同样的配置时，先点它留一份备份。', en: 'Before moving machines, reinstalling, or sharing a setup, click it to keep a backup.' },
  'tour.connectionsExportCallout': { zh: '导出的 json 里密钥是完整保留的（用它才能原样恢复），别随手发给别人。', en: 'The exported json keeps secrets in full (needed to restore exactly) — do not casually send it to others.' },
  'tour.connDialogPluginsTitle': { zh: '管理窗 · 插件（第二道开关）', en: 'Manage window · plugins (second switch)' },
  'tour.connDialogPluginsBody1': { zh: '这个 **「插件」** 按钮最关键：点开它，会列出所有插件，你在这里为**当前这个账号**勾选要启用哪些插件。', en: 'This **"Plugins"** button is the key one: click it to list all plugins, and here you tick which plugins to enable **for this specific account**.' },
  'tour.connDialogPluginsBody2': { zh: '这就是前面说的第二道开关——插件在「插件」页开了总开关后，**还要在这里勾选**，才会真正在这个连接上加载。', en: 'This is the second switch mentioned earlier — after the global switch on the Plugins page, you must also **tick here** for it to actually load on this connection.' },
  'tour.connDialogPluginsCallout': { zh: '记住：插件页总开关（全局）+ 这里的账号勾选（局部），两处都开才生效。', en: 'Remember: Plugins page global switch + this account tick — both must be on to take effect.' },
  'tour.connDialogEnableTitle': { zh: '管理窗 · 启用开关', en: 'Manage window · enable switch' },
  'tour.connDialogEnableBody1': { zh: '管理窗打开了。最上面这一行就是这个连接的 **启用 / 关闭** 开关。', en: 'The manage window is open. The top row is this connection’s **enable / disable** switch.' },
  'tour.connDialogEnableBody2': { zh: '往下还能**编辑**名称、地址、端口、Token，以及**复制**监听地址、设置**重连策略**、**删除**连接。', en: 'Below you can also **edit** name, address, port, Token, **copy** the listen address, set a **reconnect policy**, and **delete** the connection.' },
  'tour.connectionsCardTitle': { zh: '点开连接卡片', en: 'Open a connection card' },
  'tour.connectionsCardBody1': { zh: '刚才是「怎么新建」，现在看「已有的连接怎么管」。', en: 'That was "how to create"; now "how to manage existing connections".' },
  'tour.connectionsCardBody2': { zh: '每张卡片就是一个连接。**点一下它**会弹出「管理」窗。下一步我直接帮你打开。', en: 'Each card is one connection. **Click it** to open the "Manage" window. Next I will open one for you.' },
  'tour.connFormSubmitTitle': { zh: '第 3 步 · 点「添加」', en: 'Step 3 · click "Add"' },
  'tour.connFormSubmitBody1': { zh: '填好后点 **添加**，连接就会出现在列表里——但**默认是关闭的**，记得点开它再启用。', en: 'After filling, click **Add** — the connection appears in the list, but it is **off by default**, so turn it on to enable it.' },
  'tour.connFormSubmitBody2': { zh: '然后到 NapCat 等客户端把 **WebSocket 客户端** 指向 `ws://本机IP:端口`，Token 与这里一致，即可连上。', en: 'Then point the **WebSocket client** in NapCat / etc. to `ws://this-IP:port`, with a matching Token, to connect.' },
  'tour.connFormSubmitCallout': { zh: 'QQ 官方 / KOOK 填的是 AppID+AppSecret / 机器人 Token；微信则是添加后扫码登录——套路一样，按表单提示填即可。', en: 'QQ official / KOOK use AppID+AppSecret / bot Token; WeChat scans a QR after adding — same idea, just follow the form hints.' },
  'tour.connFormTokenTitle': { zh: '连接项 · Access Token（可选）', en: 'Connection item · Access Token (optional)' },
  'tour.connFormTokenBody1': { zh: '**Access Token**：连接口令，可**留空**。', en: '**Access Token**: connection password, can be **left blank**.' },
  'tour.connFormTokenBody2': { zh: '若填了，NapCat 那边要填**一模一样**的 Token 才能连上，相当于加把锁防止别人乱连。', en: 'If set, NapCat must use the **exact same** token to connect — like a lock keeping others out.' },
  'tour.connFormPortTitle': { zh: '连接项 · 监听端口', en: 'Connection item · listen port' },
  'tour.connFormPortBody1': { zh: '**监听端口**：等待连接的端口号，如 **6700**。', en: '**Listen port**: the port to wait for connections on, e.g. **6700**.' },
  'tour.connFormPortBody2': { zh: '记住这个端口——等下要在 NapCat 里把 WebSocket 客户端指向 `ws://本机IP:这个端口`。', en: 'Remember this port — you will point the WebSocket client in NapCat to `ws://this-IP:this-port` next.' },
  'tour.connFormPortCallout': { zh: '端口别和后台端口(默认8787)或其他程序冲突；两个连接也不能用同一端口。', en: 'Do not conflict with the backend port (default 8787) or other programs; two connections cannot share one port.' },
  'tour.connFormHostTitle': { zh: '连接项 · 监听地址', en: 'Connection item · listen address' },
  'tour.connFormHostBody1': { zh: '**监听地址**：咔咔珂在哪个网卡上等 NapCat 连进来。', en: '**Listen address**: which network interface Kakake waits on for NapCat to connect.' },
  'tour.connFormHostBody2': { zh: '一般填 **0.0.0.0**（所有网卡都可连，别的设备 / 容器也能接入）；只想本机连就填 127.0.0.1。', en: 'Usually **0.0.0.0** (any interface, so other devices / containers can connect); use 127.0.0.1 if only local.' },
  'tour.connFormNameTitle': { zh: '连接项 · 名称', en: 'Connection item · name' },
  'tour.connFormNameBody1': { zh: '**名称**：给这个连接起个好认的名字，随便填，只是列表里显示用，不影响连接。', en: '**Name**: give this connection a recognizable name — anything you like; it is only shown in the list and does not affect the connection.' },
  'tour.connFormNameBody2': { zh: '例如「主号 NapCat」「测试号」。', en: 'For example "Main NapCat" or "Test account".' },
  'tour.connFormTitle': { zh: '第 2 步 · 填写连接（以反向 WS 为例）', en: 'Step 2 · fill the connection (reverse WS example)' },
  'tour.connFormBody1': { zh: '选「反向 WS」后就进到这个填写表单。', en: 'After picking "Reverse WS" you get this form.' },
  'tour.connFormBody2': { zh: '整张表单就这几栏，接下来我一栏一栏讲清楚每一项填什么。', en: 'It only has a few fields; I will explain each one.' },
  'tour.connTypeModalTitle': { zh: '第 1 步 · 选择接入方式', en: 'Step 1 · choose access method' },
  'tour.connTypeModalBody1': { zh: '点「添加」后先弹出这个「选择连接类型」列表，按你的机器人平台挑一个：', en: 'After clicking "Add", this "choose connection type" list pops up; pick one for your bot platform:' },
  'tour.connTypeModalBody2': { zh: '**反向 WS**（NapCat 等 OneBot 最常用）、**正向 WS / HTTP / HTTP-SSE / HTTP 客户端**、**QQ 官方**（WS / HTTPS）、**KOOK**、**微信 AI×BOT**。', en: '**Reverse WS** (most common for NapCat and other OneBot), **Forward WS / HTTP / HTTP-SSE / HTTP client**, **QQ official** (WS / HTTPS), **KOOK**, **WeChat AI×BOT**.' },
  'tour.connTypeModalCallout': { zh: '拿不准就选「反向 WS」，它配 NapCat 最省心；下面我就以它为例往下走。', en: 'Not sure? Pick "Reverse WS" — it pairs most painlessly with NapCat; I will use it as the example below.' },
  'tour.connectionsAddTitle': { zh: '添加连接', en: 'Add connection' },
  'tour.connectionsAddBody1': { zh: '**顶栏右侧**这个 **＋** 就是「添加连接」。', en: 'The **＋** at the **top-right** is "Add connection".' },
  'tour.connectionsAddBody2': { zh: '不管你现在有没有连接，我都直接帮你点开它，带你把整个添加流程和每一项要填什么走一遍。', en: 'Whether or not you have any yet, I will open it for you and walk through the whole add flow and what each field means.' },
  'tour.connectionsAddCallout': { zh: '新添加的连接默认是「关闭」的，需要你手动启用后才会工作。', en: 'A newly added connection is **off** by default — you must enable it manually before it works.' },
  'tour.navConnectionsTitle': { zh: '第一步 · 连接', en: 'Step 1 · Connections' },
  'tour.navConnectionsBody1': { zh: '机器人要先「连上」才能收发消息，一切从 **连接** 页开始。', en: 'The bot must first **connect** to send and receive messages — everything starts on the **Connections** page.' },
  'tour.navConnectionsBody2': { zh: '点这里进入连接管理。', en: 'Click here to enter connection management.' },
  'tour.dashStatLoadedTitle': { zh: '④ 已加载', en: '④ Loaded' },
  'tour.dashStatLoadedBody1': { zh: '**已加载**：此刻真正在跑的插件数。', en: '**Loaded**: how many plugins are actually running right now.' },
  'tour.dashStatLoadedBody2': { zh: '这个数 **> 0** 才说明插件真的在工作；装了插件但这里是 0，多半是「两道开关」没都打开（后面插件页会细讲）。', en: 'This must be **> 0** for plugins to really work; if you installed plugins but this is 0, the **two switches** are probably not both on (covered later on the Plugins page).' },
  'tour.dashStatPluginsTitle': { zh: '③ 插件总数', en: '③ Total plugins' },
  'tour.dashStatPluginsBody1': { zh: '**插件总数**：本地已安装的插件数量（不代表都在运行）。', en: '**Total plugins**: how many plugins are installed locally (not all necessarily running).' },
  'tour.dashStatPluginsBody2': { zh: '对应「插件」页里的卡片总数。', en: 'Matches the total card count on the **Plugins** page.' },
  'tour.dashStatConnectedTitle': { zh: '② 已连入', en: '② Connected' },
  'tour.dashStatConnectedBody1': { zh: '**已连入**：真正连上线的连接数。', en: '**Connected**: the number of connections actually online.' },
  'tour.dashStatConnectedBody2': { zh: '这个数 **> 0** 才说明机器人确实连通了；一直是 0 就要回连接页检查启用状态和客户端配置。', en: 'This must be **> 0** for the bot to truly be connected; if it stays 0, go back to Connections and check the enable switch and client config.' },
  'tour.dashStatListenTitle': { zh: '① 监听配置', en: '① Listen config' },
  'tour.dashStatListenBody1': { zh: '**监听配置**：你一共添加了多少个连接（不管有没有连上、有没有启用）。', en: '**Listen config**: how many connections you have added in total (whether connected or enabled).' },
  'tour.dashStatListenBody2': { zh: '也就是「连接」页里的卡片总数。', en: 'That is the total number of cards on the **Connections** page.' },
  'tour.dashboardStatsTitle': { zh: '运行状态一览', en: 'Runtime status at a glance' },
  'tour.dashboardStatsBody1': { zh: '概览顶部这一排是**四个关键数字**，一眼看出机器人是否在正常工作。', en: 'The top row of the overview shows **four key numbers** that tell you at a glance whether the bot is working.' },
  'tour.dashboardStatsBody2': { zh: '接下来我一个一个带你看它们分别代表什么。', en: 'Next I will walk you through what each one means.' },
  'tour.dashboardStatsCallout': { zh: '下方还会列出每个连接的实时状态，红色失败的可直接点卡片里的「重试」。', en: 'Below it also lists each connection’s live status; a red failure can be retried by clicking **Retry** on its card.' },
  'tour.navToggleTitle': { zh: '顶栏最左 · 开关侧边栏', en: 'Top bar far-left · toggle sidebar' },
  'tour.navToggleBody1': { zh: '顶栏最左边这个按钮就是**侧边栏开关**，点一下展开、再点一下收起。', en: 'This button at the far left of the top bar is the **sidebar toggle**: click to expand, click again to collapse.' },
  'tour.navToggleBody2': { zh: '**电脑**点这个按钮开合；**手机**上点侧边栏以外的空白处即可收起。', en: 'On **desktop** click this button to open/close; on **mobile** tap anywhere outside the sidebar to close it.' },
  'tour.navToggleBody3': { zh: '侧边栏默认收起，而且切换界面时不会自动关掉——它会保持你上一次的选择。', en: 'The sidebar is collapsed by default, and it stays the way you left it when you switch screens — it does not auto-close.' },
  'tour.navToggleCallout': { zh: '宽窄可以在「设置 → 界面外观 → 侧边栏宽度」里分别调电脑和手机两种。', en: 'Widths can be tuned separately for desktop and mobile under **Settings → Appearance → Sidebar width**.' },
  'tour.navEditTitle': { zh: '侧边栏底部 · 自定义导航', en: 'Sidebar bottom · customize navigation' },
  'tour.navEditBody1': { zh: '侧边栏最底下、GitHub 图标**左边**这个铅笔按钮，点它进入**导航编辑模式**：每一项都能上下拖动改顺序，右边还能决定它显不显示。', en: 'This pencil button at the very bottom of the sidebar, **left** of the GitHub icon, enters **navigation edit mode**: drag any item to reorder it, and use the control on the right to decide whether it shows.' },
  'tour.navEditBody2': { zh: '**排在第一位的就是首页**：下次打开控制台、或直接敲域名进来，都会先停在它。但你**手动点回「系统总览」**之后再刷新，仍停在总览——一次会话里以你的点击为准。', en: '**The first item is your home page**: next time you open the console, or arrive by typing the domain, it lands there first. But if you **click back to Overview yourself** and then refresh, you stay on Overview — within a session your click wins.' },
  'tour.navEditBody3': { zh: '点右边的**叉号**，这一项名字变淡，退出编辑后它就不出现在侧边栏里了；叉号同时变成**刷新**图标，点一下即可恢复显示。', en: 'Click the **cross** on the right: the name dims and, once you leave edit mode, it disappears from the sidebar. The cross becomes a **refresh** icon — click it to bring the item back.' },
  'tour.navEditCallout': { zh: '只有「实用工具、开放平台、智能助手、模拟消息」这四项允许隐藏，其余是核心入口、不能移除。改完点铅笔位上的**对勾**才会保存，设置存在 data/nav-layout.json 里（跟账号走，换浏览器、清缓存、换设备都还在）。', en: 'Only **Tools, Open Platform, AI Assistant, and Simulate** can be hidden; the rest are core entries and cannot be removed. Press the **checkmark** where the pencil was to save. The layout lives in data/nav-layout.json (tied to your account, so it survives browser switches, cache clears, and other devices).' },
  'tour.dashboardTitle': { zh: '概览页', en: 'Overview' },
  'tour.dashboardBody1': { zh: '这里是控制台首页，进来先看它。', en: 'This is the console home page — start here.' },
  'tour.dashboardBody2': { zh: '这排就是**主导航**，所有功能都从这里进：概览、连接、插件、资源、工具、开放平台、智能助手、模拟、日志、设置。', en: 'This row is the **main navigation**: every feature lives under it — Overview, Connections, Plugins, Resources, Tools, Open Platform, AI Assistant, Simulate, Logs, Settings.' },
  'tour.dashboardBody3': { zh: '它装在**侧边栏**里，而侧边栏默认是收起的——用顶栏最左边的按钮就能呼出来。', en: 'It sits in the **sidebar**, which is collapsed by default — use the button at the far left of the top bar to open it.' },
  'tour.welcomeTitle': { zh: '欢迎使用咔咔珂', en: 'Welcome to Kakake' },
  'tour.welcomeP1': { zh: '第一次进来可能有点摸不着头脑？跟着', en: 'First time in and a bit lost? Follow' },
  'tour.welcomeTour': { zh: '产品导览', en: 'the product tour' },
  'tour.welcomeP2': { zh: '走一遍，带你逐个认识每个功能在哪、怎么点，尤其是最容易绕晕的', en: 'for a walk-through of where each feature is and how to click it — especially the easiest to get tangled:' },
  'tour.welcomeOrder': { zh: '「连接 + 插件」启用顺序', en: 'the "connection + plugin" enable order' },
  'tour.welcomeP3': { zh: '步骤比较多，随时可以「跳过教程」，之后在设置里也能再看。', en: 'There are many steps; you can "skip tutorial" anytime, and revisit it later in Settings.' },
  'tour.skipBtn': { zh: '跳过教程', en: 'Skip tutorial' },
  'tour.startBtn': { zh: '开始教程', en: 'Start tutorial' },
  'tour.stepLabel': { zh: '步骤 {n} / {total}', en: 'Step {n} / {total}' },
  'tour.closeTourAria': { zh: '关闭导览', en: 'Close tour' },
  'tour.prevBtn': { zh: '上一步', en: 'Previous' },
  'tour.nextBtn': { zh: '下一步', en: 'Next' },
  'tour.doneBtn': { zh: '完成', en: 'Done' },
});
